function bpsConsolidatedSelections(kind,definition,saved){
 const selections=Object.fromEntries(definition.groups.map(g=>[g.key,(saved?.selections[g.key]||[]).filter(v=>g.choices.includes(v))]));
 if(saved?.definition?.consolidation_version===boot.bps_consolidation.version)return selections;
 for(const alias of boot.bps_consolidation.aliases){if(alias.target_kind!==kind)continue;const source=last(alias.source_kind);if(!source?.selections[alias.source_group]?.includes(alias.source_value))continue;const values=selections[alias.target_group];if(!values)continue;selections[alias.target_group]=values.filter(v=>!definition.exclusive.includes(v));if(!selections[alias.target_group].includes(alias.target_value))selections[alias.target_group].push(alias.target_value);}
 return selections;
}
function bpsSymptomSelectionState(){
 const saved=last('biopsychosocial_symptoms'),ratings={...saved?.ratings},conflicts={};
 if(saved?.definition?.consolidation_version===boot.bps_consolidation.version)return {ratings,conflicts};
 for(const [source,target] of Object.entries(boot.bps_consolidation.symptom_aliases)){if(!ratings[source])continue;if(ratings[target]&&ratings[target]!==ratings[source]){conflicts[target]=[ratings[target],ratings[source]];delete ratings[target];}else ratings[target]=ratings[source];delete ratings[source];}
 return {ratings,conflicts};
}


function insuranceIntakeDemoView(){return '';}
function bindInsuranceIntakeDemo(){
 const source=document.getElementById('fictional-insurance-intake'),target=document.querySelector('form[data-action="insurance"]');if(!source||!target)return;
 document.getElementById('load-fictional-coverage').addEventListener('click',()=>{
  const example={carrier:'Fictional Example Health',street_address_1:'100 Example Avenue',street_address_2:'Suite 200',city:'Example City',state:'KS',zip:'00123',group_number:'000567',payer_id:'00199',provider_phone:'555-0100',patient_first_name:chart.patient.first_name||'',patient_last_name:chart.patient.last_name||'',patient_dob:chart.patient.dob||'',subscriber_relationship:'Self',insured_first_name:chart.patient.first_name||'',insured_last_name:chart.patient.last_name||'',insured_dob:chart.patient.dob||'',plan_name:'Fictional Outpatient Plan',member_id:'000012345',coverage_notes:'Fictional patient-reported intake example; benefits have not been verified.'};
  for(const [key,value] of Object.entries(example))source.elements.namedItem(key).value=value;dirty=true;
 });
 source.addEventListener('input',()=>dirty=true);
 source.addEventListener('submit',event=>{
  event.preventDefault();const values=Object.fromEntries(new FormData(source)),fields=insuranceDisplayFields.map(([key])=>key),changes=fields.filter(key=>String(values[key]||'').trim()!==''&&target.elements.namedItem(key).value!==values[key]);
  const conflicts=changes.filter(key=>target.elements.namedItem(key).value.trim()!=='');
  if(conflicts.length&&!window.confirm(`The fictional intake differs from ${conflicts.length} existing insurance form value(s). Replace those draft values for this demo patient? Saved insurance history is retained. Cancel to keep all existing form values.`))return;
  for(const key of changes)target.elements.namedItem(key).value=values[key];
  if(changes.length)dirty=true;
  const status=document.getElementById('insurance-intake-demo-status');status.textContent=changes.length?`Populated ${changes.length} insurance field(s) from the fictional intake for this demo chart. Blank intake fields left existing values unchanged. Review the form below and select Save insurance to retain it.`:'No differing nonblank intake values to copy. Existing insurance values are unchanged.';
  target.scrollIntoView({behavior:'smooth',block:'start'});
 });
}

function medicationIntakeDemoView(){return '';}
function bindMedicationIntakeDemo(){
 const source=document.getElementById('fictional-medication-intake'),target=document.querySelector('form[data-action="biopsychosocial_medication"]');if(!source||!target)return;
 const message=text=>document.getElementById('medication-intake-demo-status').textContent=text;
 const status=source.elements.status,end=source.elements.end_date;status.addEventListener('change',()=>{end.disabled=status.value==='Current';if(end.disabled)end.value='';});
 source.querySelectorAll('[name=benefit]').forEach(input=>input.addEventListener('change',()=>{if(input.checked)source.querySelectorAll('[name=benefit]').forEach(other=>{if(other!==input)other.checked=false;});}));
 source.addEventListener('input',()=>dirty=true);
 document.getElementById('load-fictional-medication').addEventListener('click',()=>{const sample={medication:'Fictional sample medication',status:'Current',dosage:'Fictional dose',frequency:'Fictional schedule',start_date:'2020-01-01',end_date:'',prescribing_physician:'Fictional physician'};for(const [key,value] of Object.entries(sample))source.elements.namedItem(key).value=value;source.querySelectorAll('[name=benefit]').forEach(input=>input.checked=input.value==='Beneficial');end.disabled=true;dirty=true;});
 source.addEventListener('submit',event=>{
  event.preventDefault();if(target.elements.prior_id.value){message('Finish or cancel editing the existing medication before populating a new intake medication.');return;}
  const data=collectBpsMedication(new FormData(source)),keys=['medication','status','dosage','frequency','start_date','end_date','prescribing_physician'];
  const existing=keys.some(key=>target.elements.namedItem(key).value.trim()!==''&&target.elements.namedItem(key).value!==data[key])||[...target.querySelectorAll('[name=benefit]')].some(input=>input.checked&&input.value!==data.benefit);
  if(existing&&!confirm('Replace the unsaved medication form values with this fictional intake entry? Existing saved medication history is retained.'))return;
  for(const key of keys)target.elements.namedItem(key).value=data[key]||'';
  target.querySelectorAll('[name=benefit]').forEach(input=>input.checked=input.value===data.benefit);
  target.elements.status.dispatchEvent(new Event('change'));target.elements.end_date.value=data.status==='Current'?'':data.end_date||'';target.dataset.modified='true';dirty=true;message('Medication fields populated from the fictional intake. Review and select Add medication to save this entry for the selected demo chart.');target.scrollIntoView({behavior:'smooth',block:'start'});
 });
 const allergySource=document.getElementById('fictional-medication-allergies'),allergyTarget=document.querySelector('form[data-action="medication_allergies"]');
 allergySource.addEventListener('input',()=>dirty=true);allergySource.addEventListener('submit',event=>{event.preventDefault();const status=allergySource.elements.allergy_status.value,notes=allergySource.elements.allergy_notes.value;
 if(status==='Medication allergies reported'&&!notes.trim()){message('Describe the fictional medication allergy or reaction.');return;}
 if(status==='No known medication allergies'&&notes.trim()){message('Choose Medication allergies reported or clear the fictional allergy notes.');return;}
 const changed=allergyTarget.elements.allergy_status.value!==status||allergyTarget.elements.allergy_notes.value!==notes;
 if(changed&&(allergyTarget.elements.allergy_notes.value||allergyTarget.elements.allergy_status.value!=='Not yet reviewed')&&!confirm('Replace the unsaved medication allergy form values with this fictional intake response? Saved allergy history is retained.'))return;
 allergyTarget.elements.allergy_status.value=status;allergyTarget.elements.allergy_notes.value=notes;allergyTarget.dataset.modified='true';dirty=true;message('Medication allergy fields populated from the fictional intake. Review and select Save medication allergies.');allergyTarget.scrollIntoView({behavior:'smooth',block:'start'});
 });
}

function medicalSubstanceIntakeDemoView(){return '';}
function bindMedicalSubstanceIntakeDemo(){
 const source=document.getElementById('fictional-medical-substance-intake'),target=document.querySelector('form[data-action="biopsychosocial_medical_substance"]');if(!source||!target)return;
 const definition=boot.medical_substance;
 source.querySelectorAll('[data-medical-substance-group]').forEach(input=>input.addEventListener('change',()=>{if(!input.checked)return;source.querySelectorAll('[data-medical-substance-group]').forEach(other=>{if(other!==input&&other.dataset.medicalSubstanceGroup===input.dataset.medicalSubstanceGroup&&(definition.exclusive.includes(input.value)||definition.exclusive.includes(other.value)))other.checked=false;});}));
 source.addEventListener('input',()=>dirty=true);
 document.getElementById('load-fictional-medical-history').addEventListener('click',()=>{const selections={medical_conditions:['Asthma'],medical_care:['Surgery'],health_impact:['Sleep disruption'],substances:['Alcohol'],patterns:['Past use reported'],routes:['Oral / swallowed'],effects:['None reported'],recovery:['Outpatient treatment']};
 source.querySelectorAll('[data-medical-substance-group]').forEach(input=>input.checked=(selections[input.dataset.medicalSubstanceGroup]||[]).includes(input.value));
 const notes={medical_notes:'Fictional history: condition and surgery dates not supplied.',use_notes:'Fictional patient-reported past use; amounts and dates not supplied.',effects_notes:'Fictional patient-reported response; not independently verified.',recovery_notes:'Fictional prior outpatient course; dates not supplied.',source_notes:'Fictional intake page 7 demonstration.',primary_care_provider:'Fictional primary care clinician',pcp_phone:'555-0100',other_allergies:'Fictional pollen reaction',behavioral_addictions:'Fictional example; no further details supplied.'};for(const [key,value] of Object.entries(notes))source.elements.namedItem(key).value=value;dirty=true;});
 source.addEventListener('submit',event=>{event.preventDefault();const data=collectBpsMedicalSubstance(new FormData(source));let conflicts=0;
 for(const g of definition.groups){const selected=data.selections[g.key],existing=[...target.querySelectorAll('[data-medical-substance-group]')].filter(input=>input.dataset.medicalSubstanceGroup===g.key&&input.checked).map(input=>input.value);if(selected.length&&existing.length&&JSON.stringify([...selected].sort())!==JSON.stringify([...existing].sort()))conflicts++;}
 for(const key of Object.keys(definition.notes))if(data.notes[key].trim()&&target.elements.namedItem(key).value.trim()&&target.elements.namedItem(key).value!==data.notes[key])conflicts++;
 if(conflicts&&!confirm(`The fictional intake differs from ${conflicts} existing history group(s) or detail field(s). Replace those draft values? Saved history snapshots are retained.`))return;
 for(const g of definition.groups)if(data.selections[g.key].length)target.querySelectorAll('[data-medical-substance-group]').forEach(input=>{if(input.dataset.medicalSubstanceGroup===g.key)input.checked=data.selections[g.key].includes(input.value);});
 for(const key of Object.keys(definition.notes))if(data.notes[key].trim())target.elements.namedItem(key).value=data.notes[key];
 dirty=true;document.getElementById('medical-substance-intake-status').textContent='History fields populated from the fictional intake. Unanswered groups and blank details retained their existing values. Review and select Save medical & substance use history above.';target.scrollIntoView({behavior:'smooth',block:'start'});
 });
}

function signedNoticesView(){const docs=records('document').filter(r=>r.category==='Legal Notice');return `${legalRoutingView()}<section class="card"><h2>Signed Notices — intake PDF copies</h2><p>Upload a separate fictional PDF for each intake form, pages 11–21, for ${esc(chart.patient.name)}. The clinic intake provides Print / Save as PDF for each form. Real clinic records are not connected to this demo.</p><form id="signed-notice-upload"><label class="field">Intake form<select name="notice_form_id" required><option value="">Choose form</option>${boot.legal_forms.map(f=>`<option value="${f.id}">Page ${f.page}: ${esc(f.section)} — ${esc(f.category)}</option>`).join('')}</select></label><label class="field">Copy status<select name="copy_status"><option>Decision / acknowledgment record</option><option>Signed copy supplied</option><option>Draft / unsigned copy</option></select></label><label class="field">Name shown on signature<input name="signer_name" maxlength="200" autocomplete="off"></label><label class="field">Signature date shown on copy<input name="signature_date" type="date"></label><label class="field">Source document revision<input name="source_revision" value="2026-11-02-directory-1" maxlength="80"></label><label class="field">Office review notes<textarea name="review_notes" rows="2" maxlength="4000"></textarea></label><label class="field">Fictional PDF copy<input type="file" name="upload" accept="application/pdf" required></label><label class="check"><input type="checkbox" name="synthetic_confirmed" required>This is a fictional sample document, with no real patient information.</label><p class="hint">Use the revision printed on the PDF; historical copies keep their original page numbers. Each PDF up to 150 KB; all chart sample attachments together up to 600 KB. A copy does not verify a signature, representative authority, current consent or permission to disclose.</p><button type="submit">Save PDF in Signed Notices</button><p id="signed-notice-status" role="status"></p></form></section><section class="card"><h2>Saved notice copies</h2>${docs.toReversed().map(r=>`<article class="record"><h3>${r.intake_page?'Page '+r.intake_page+': ':''}${esc(r.form_title||r.title)}</h3><p>${esc(r.copy_status||'Legacy copy — status not recorded')} · ${esc(r.form_category||'Legacy legal notice')} · ${esc(when(r.created))}</p><p>Signer: ${esc(r.signer_name||'Not recorded')} · Signature date: ${esc(r.signature_date||'Not recorded')} · Revision: ${esc(r.source_revision||'Not recorded')}</p><p>${esc(r.verification_status||'Unverified copy')}</p>${r.review_notes?`<p>${esc(r.review_notes)}</p>`:''}<p class="hash">PDF SHA-256: ${esc(r.content_sha256)}</p>${r.mime_type==='application/pdf'?noticePdfLink(r):''} <button type="button" class="secondary" data-download-notice="${esc(r.id)}">Download original copy</button></article>`).join('')||'<p>No saved notice PDFs in this chart.</p>'}</section>`;}
function bindSignedNotices(){clearNoticePdfLinks();bindNoticePdfLinks();bindLegalRouting();const f=document.getElementById('signed-notice-upload');if(!f)return;f.addEventListener('input',()=>dirty=true);f.addEventListener('submit',async event=>{event.preventDefault();const button=f.querySelector('[type=submit]'),pid=patientId;button.disabled=true;try{const fd=new FormData(f),file=f.elements.upload.files[0],def=boot.legal_forms.find(d=>d.id===fd.get('notice_form_id'));if(!def)throw Error('Choose an intake form.');if(!fd.has('synthetic_confirmed'))throw Error('Confirm the PDF contains fictional sample information only.');if(!file?.size||file.type!=='application/pdf'||file.size>153600)throw Error('Choose a PDF copy up to 150 KB.');const dataURL=await photoDataURL(file);if(pid!==patientId||!f.isConnected)return;await api('/api/save',{method:'POST',body:JSON.stringify({patient_id:pid,action:'document',data:{...Object.fromEntries(fd),title:`Page ${def.page}: ${def.section}`,category:'Legal Notice',synthetic_confirmed:true,data_url:dataURL,filename:file.name}})});dirty=false;await reload();message('Fictional PDF saved in this patient’s Signed Notices. Signature and legal authority remain unverified.');}catch(error){if(f.isConnected)document.getElementById('signed-notice-status').textContent=error.message;}finally{if(f.isConnected)button.disabled=false;}});document.querySelectorAll('[data-download-notice]').forEach(button=>button.addEventListener('click',()=>{const record=records('document').find(r=>r.id===button.dataset.downloadNotice);if(!record)return;const a=document.createElement('a');a.href=record.data_url;a.download=record.filename||record.title.replace(/[^a-zA-Z0-9 _-]/g,'_')+(record.mime_type==='application/pdf'?'.pdf':'.jpg');document.body.append(a);a.click();a.remove();}));}

function legalRoutingView(){const history=records('legal_routing'),latest=history.at(-1);return `<section class="card"><h2>Page 10 — Legal forms questionnaire and results</h2><p>Duplicate fictional intake answers into ${esc(chart.patient.name)}’s Signed Notices. This guide identifies forms to review; it never signs a form or authorizes a release.</p><p><button type="button" class="secondary" id="routing-demo-example">Load fictional example</button></p><label class="field">Import fictional page 10 result<input id="routing-demo-import" type="file" accept="application/json,.json"></label><p class="hint">Use the file downloaded from the clinic’s non-saving intake preview, or answer the same questions below. Real patient records are not connected.</p><form id="legal-routing-form">${boot.legal_routing.questions.map(q=>`<fieldset aria-describedby="emr-routing-help-${q.id}"><legend>${esc(q.label)}</legend><div class="choices">${q.options.map(o=>`<label><input type="radio" name="${q.id}" value="${o}" ${latest?.answers[q.id]===o?'checked':''} required>${o}</label>`).join('')}</div><p id="emr-routing-help-${q.id}">${esc(boot.legal_routing_help[q.id].text)}</p></fieldset>`).join('')}<label class="check"><input type="checkbox" name="synthetic_confirmed" required>These are fictional questionnaire answers for the currently selected demo patient.</label><button type="submit">Save questionnaire and results in Signed Notices</button><p id="legal-routing-status" role="status"></p></form></section><section class="card"><h2>Saved form requirements checklist</h2>${latest?renderLegalRoutingResult(latest):'<p>No saved questionnaire result. Answer or import page 10, then save.</p>'}${history.length>1?`<details><summary>Earlier questionnaire results (${history.length-1})</summary>${history.slice(0,-1).toReversed().map(renderLegalRoutingResult).join('')}</details>`:''}</section>`;}
function renderLegalRoutingResult(record){return `<article class="record"><h3>Page 10 questionnaire · ${esc(when(record.created))}</h3><p>${esc(record.verification_status)} · Version ${esc(record.version)}</p><section><h4>Recorded questionnaire answers</h4><dl>${record.definition.questions.map(q=>`<dt>${esc(q.label)}</dt><dd><strong>${esc(record.answers[q.id])}</strong> · ${esc(boot.legal_routing_help[q.id]?.text||'')} ${noticePdfLinks(boot.legal_routing_help[q.id]?.form_id)}</dd>`).join('')}</dl></section>${record.results.map(f=>`<div class="record"><h4>Page ${f.page}: ${esc(f.section)}</h4><p><strong>${esc(f.status)}</strong> — ${esc(f.reason)}</p><p>${esc(f.why)}</p>${noticePdfLinks(f.id)}</div>`).join('')}<p class="hash">Definition SHA-256: ${esc(record.definition_hash)}</p></article>`;}
function bindLegalRouting(){const f=document.getElementById('legal-routing-form');if(!f)return;const setAnswers=answers=>{for(const q of boot.legal_routing.questions){if(!q.options.includes(answers[q.id]))throw Error('Each questionnaire answer must be Yes, No or Unsure.');}for(const q of boot.legal_routing.questions)for(const input of f.elements[q.id])input.checked=input.value===answers[q.id];f.elements.synthetic_confirmed.checked=false;dirty=true;document.getElementById('legal-routing-status').textContent='Fictional answers loaded for '+chart.patient.name+'. Review them, confirm the selected chart and save to record the results.';};f.addEventListener('input',()=>dirty=true);document.getElementById('routing-demo-example').addEventListener('click',()=>setAnswers(Object.fromEntries(boot.legal_routing.questions.map(q=>[q.id,['telehealth','electronic'].includes(q.id)?'Yes':'No']))));document.getElementById('routing-demo-import').addEventListener('change',async event=>{const file=event.target.files[0],pid=patientId;try{if(!file||file.size>32768)throw Error('Use a fictional questionnaire JSON file up to 32 KB.');const data=JSON.parse(await file.text());if(pid!==patientId||!f.isConnected)return;if(data.format!=='fictional-legal-routing/1'||data.synthetic!==true||data.version!==boot.legal_routing.version||!data.answers||Object.keys(data.answers).sort().join(',')!==boot.legal_routing.questions.map(q=>q.id).sort().join(','))throw Error('Use the recognized fictional page 10 export.');setAnswers(data.answers);}catch(e){if(f.isConnected)document.getElementById('legal-routing-status').textContent=e.message;}});f.addEventListener('submit',async event=>{event.preventDefault();const pid=patientId,button=f.querySelector('[type=submit]');button.disabled=true;try{const fd=new FormData(f);if(!fd.has('synthetic_confirmed'))throw Error('Confirm these are fictional answers.');const answers=Object.fromEntries(boot.legal_routing.questions.map(q=>[q.id,fd.get(q.id)]));await api('/api/save',{method:'POST',body:JSON.stringify({patient_id:pid,action:'legal_routing',data:{version:boot.legal_routing.version,answers,synthetic_confirmed:true}})});if(pid!==patientId||!f.isConnected)return;dirty=false;await reload();message('Page 10 questionnaire and form requirements saved in this patient’s Signed Notices. No forms were signed automatically.');}catch(e){if(f.isConnected)document.getElementById('legal-routing-status').textContent=e.message;}finally{if(f.isConnected)button.disabled=false;}});}

function noticePdfLink(record){return `<a href="#" data-open-notice="${esc(record.id)}" target="_blank" rel="noopener noreferrer">Open PDF — ${esc(record.filename||record.form_title||record.title)} (${esc(when(record.created))})</a>`;}
function noticePdfLinks(formId){const copies=records('document').filter(r=>r.category==='Legal Notice'&&r.mime_type==='application/pdf'&&r.notice_form_id===formId);return copies.length?`<ul>${copies.toReversed().map(r=>`<li>${noticePdfLink(r)} · ${esc(r.copy_status||'Status not recorded')}</li>`).join('')}</ul>`:'<p class="hint">No PDF copy saved for this form in this patient’s record.</p>';}
function bindNoticePdfLinks(){document.querySelectorAll('[data-open-notice]').forEach(link=>{const record=records('document').find(r=>r.id===link.dataset.openNotice);if(!record||record.mime_type!=='application/pdf')return;let url=noticePdfObjectUrls.get(record.id);if(!url){const raw=atob(record.data_url.split(',')[1]),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));noticePdfObjectUrls.set(record.id,url);}link.href=url;});}

function clearNoticePdfLinks(){for(const url of noticePdfObjectUrls.values())URL.revokeObjectURL(url);noticePdfObjectUrls.clear();}
window.addEventListener('pagehide',clearNoticePdfLinks);

function bpsTraumaHistoryView(){const d=boot.trauma_history,saved=last('biopsychosocial_trauma_history');return `<section class="card">${bpsSubnav()}<h2>Trauma History</h2><p id="trauma-instructions">${esc(d.instructions)}</p><p class="hint">${esc(d.limitations)}</p><p>Use the existing symptom checklist for broader symptom documentation. If a current safety concern is identified, assess and address it during the encounter; saving this page does not notify anyone.</p></section>${form('biopsychosocial_trauma_history',`<section class="card"><div class="personal-history-grid">${d.groups.map(g=>`<fieldset aria-describedby="trauma-instructions"><legend>${esc(g.label)}</legend>${g.choices.map((v,i)=>`<label class="check" for="trauma-${g.key}-${i}"><input type="checkbox" id="trauma-${g.key}-${i}" name="${g.key}" value="${esc(v)}" data-trauma-group="${g.key}" ${(saved?.selections[g.key]||[]).includes(v)?'checked':''}>${esc(v)}</label>`).join('')}</fieldset>`).join('')}</div></section><section class="card"><details><summary>Optional context, follow-up and source notes</summary>${Object.entries(d.notes).map(([key,label])=>`<label class="field" for="trauma-${key}">${esc(label)}<textarea id="trauma-${key}" name="${key}" rows="3" maxlength="4000">${esc(saved?.notes[key]||'')}</textarea></label>`).join('')}</details></section>`,'Save trauma history')}<section class="card"><h2>Saved Trauma History</h2>${records('biopsychosocial_trauma_history').toReversed().map(r=>`<details class="record"><summary>${esc(when(r.created))}</summary><dl>${r.definition.groups.map(g=>`<dt>${esc(g.label)}</dt><dd>${esc(r.selections[g.key]?.join('; ')||'Not assessed')}</dd>`).join('')}${Object.entries(r.definition.notes).filter(([k])=>r.notes[k]).map(([k,label])=>`<dt>${esc(label)}</dt><dd>${esc(r.notes[k])}</dd>`).join('')}</dl></details>`).join('')||'<p>No trauma history saved.</p>'}</section>`;}
function bindBpsTraumaHistory(){const f=document.querySelector('form[data-action="biopsychosocial_trauma_history"]');if(!f)return;f.querySelectorAll('[data-trauma-group]').forEach(input=>input.addEventListener('change',()=>{if(!input.checked)return;const exclusive=boot.trauma_history.exclusive.includes(input.value);f.querySelectorAll('[data-trauma-group]').forEach(other=>{if(other!==input&&other.dataset.traumaGroup===input.dataset.traumaGroup&&(exclusive||boot.trauma_history.exclusive.includes(other.value)))other.checked=false;});}));}
function collectBpsTraumaHistory(fd){return {selections:Object.fromEntries(boot.trauma_history.groups.map(g=>[g.key,fd.getAll(g.key)])),notes:Object.fromEntries(Object.keys(boot.trauma_history.notes).map(k=>[k,fd.get(k)||'']))};}

function assessmentAssignmentView(){return `<section class="card"><span class="pill">Patient assessment assignments</span><h2>Assign a Psychological Test</h2><p>Open Indian Creek’s assessment assignment page to choose an assessment and enter the intended recipient’s information.</p><p><a class="button-link" href="/admin/assign-test" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">Open Patient Questionnaire Assignment</a></p><p class="hint">Opens the clinic workspace in a separate tab. Sign in there with an authorized clinic administrator account and complete its required security verification. Confirm the recipient in that workspace; no demo patient information is sent automatically.</p></section>`;}
